Here's how to write modern MSTest tests for your `DataFetcher` using async patterns, timeouts, and cancellation tokens:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _fetcher;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        _fetcher = new DataFetcher(new HttpClient(_handler));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_SuccessfulResponse_ReturnsContent()
    {
        // Arrange
        _handler.ResponseContent = "hello world";

        // Act
        var result = await _fetcher.FetchAsync(
            "https://example.com/data", _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_NotFoundResponse_ThrowsHttpRequestException()
    {
        // Arrange
        _handler.StatusCode = System.Net.HttpStatusCode.NotFound;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _fetcher.FetchAsync(
                "https://example.com/missing", _testContext.CancellationToken));
    }

    [TestMethod]
    [Timeout(2000)]
    public async Task FetchAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        // Arrange
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // pre-cancel

        // Act & Assert
        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_TimeoutExpires_IsCancelledCooperatively()
    {
        // Arrange — handler delays longer than the test timeout
        _handler.SimulatedDelay = TimeSpan.FromSeconds(10);

        // Act & Assert — TestContext.CancellationToken fires when [Timeout] expires
        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _fetcher.FetchAsync(
                "https://example.com/slow", _testContext.CancellationToken));
    }
}
```

And the test helper:

```csharp
internal sealed class MockHttpMessageHandler : HttpMessageHandler
{
    public string ResponseContent { get; set; } = string.Empty;
    public System.Net.HttpStatusCode StatusCode { get; set; } = System.Net.HttpStatusCode.OK;
    public TimeSpan SimulatedDelay { get; set; } = TimeSpan.Zero;

    protected override async Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken cancellationToken)
    {
        if (SimulatedDelay > TimeSpan.Zero)
            await Task.Delay(SimulatedDelay, cancellationToken);

        return new HttpResponseMessage(StatusCode)
        {
            Content = new StringContent(ResponseContent)
        };
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---------|-----|
| Async tests | `async Task` return type — MSTest awaits them natively |
| Timeouts | `[Timeout(ms)]` cancels via `TestContext.CancellationToken` |
| Cooperative cancellation | Pass `_testContext.CancellationToken` into the code under test |
| Exception assertions | `Assert.ThrowsExactlyAsync<T>` — no `[ExpectedException]` |
| Constructor injection | `TestContext` injected via ctor (MSTest 3.6+), enables `readonly` fields |

The critical detail: always flow `TestContext.CancellationToken` into your awaited calls so that `[Timeout]` actually stops the test cooperatively rather than leaving orphaned tasks.
